export interface Check {
  id: string;
  suite_id: string;
  name: string;
  kind: string;
  /** `auto` = added by automatic coverage; `suggestion` = an accepted suggestion (ADR 0047). */
  origin?: 'user' | 'auto' | 'suggestion';
  /** Set on an automatic baseline that takes its thresholds and window from the coverage
   *  settings: the values shown are the ones in effect, and editing one gives the check its own. */
  inherited?: { sensitivity: CoverageLevel; baseline: CoverageLevel } | null;
  /** Check engine (ADR 0036) — `gx` (default) or `dmf` on a Snowflake connection.
   *  Optional so pre-0036 fixtures need no change. */
  engine?: string;
  expectation_type: string;
  /** DQ dimension (ADR 0038). `null` = unclassified — render it as a coverage
   *  gap, never bucket it silently. Optional so pre-0038 fixtures need no change. */
  dimension?: string | null;
  config: Record<string, unknown>;
  /** Comparison source ref (ADR 0015) — set exactly for kind='comparison'.
   *  Optional in the type so pre-0015 fixtures/readers need no change. */
  source_connection_id?: string | null;
  warn_threshold: number | null;
  fail_threshold: number | null;
  critical_threshold: number | null;
  /** Alert suppression (#370): in the future = alerts muted until then; null /
   *  past = active. Set via the snooze endpoints, never PATCH. */
  alert_snoozed_until: string | null;
  /** `false` = switched off: kept with its history, left out of every run. Optional so
   *  older fixtures need no change; absent means switched on. */
  enabled?: boolean;
}

export async function listChecks(suiteId: string): Promise<Check[]> {
  const { data } = await api.get<Check[]>(`/suites/${suiteId}/checks`);
  return data;
}

/** Fetch one check by id — backs the deep-linkable `/checks/:id/edit` page. */
export async function getCheck(suiteId: string, checkId: string): Promise<Check> {
  const { data } = await api.get<Check>(`/suites/${suiteId}/checks/${checkId}`);
  return data;
}

/** Mirrors `CheckCreate` — `kind` is `expectation` (incl. custom-SQL) or a monitor
