"""Scratch helpers: read Postgres creds from the repo .env and print URLs / manage scratch DBs."""

import sys
from pathlib import Path

import sqlalchemy as sa

ENV = Path("/Users/arijit/Coding/Python/DataQ/.env")


def creds() -> tuple[str, str]:
    kv = {}
    for line in ENV.read_text().splitlines():
        if "=" in line and not line.startswith("#"):
            k, v = line.split("=", 1)
            kv[k.strip()] = v.strip()
    return kv["POSTGRES_USER"], kv["POSTGRES_PASSWORD"]


def url(db: str) -> str:
    u, p = creds()
    return f"postgresql+psycopg2://{u}:{p}@localhost:5432/{db}"


def main() -> None:
    cmd = sys.argv[1]
    if cmd == "url":
        print(url(sys.argv[2]))
    elif cmd == "recreate":
        eng = sa.create_engine(url("postgres"), isolation_level="AUTOCOMMIT")
        with eng.connect() as c:
            c.execute(sa.text(f"DROP DATABASE IF EXISTS {sys.argv[2]}"))
            c.execute(sa.text(f"CREATE DATABASE {sys.argv[2]}"))
        print("ok")
    elif cmd == "sql":
        eng = sa.create_engine(url(sys.argv[2]))
        with eng.connect() as c:
            for row in c.execute(sa.text(sys.argv[3])):
                print(tuple(row))


if __name__ == "__main__":
    main()

